/* ---- Phase 3: inbound events + outbound webhook subscriptions (Zapier/Make/n8n) ---- */
// Records the event (kept as Zapier sample data), then POSTs it to every subscribed
// target. Bounded: 10 subscriptions, 5s each, delivered in parallel.
async function hookEmit(env, ws, event, data) {
  const key = env && env.AUTOMATION_SECRET;
  if (!key || !UUIDRE.test(String(ws || ''))) return;
  let out;
  try { out = await sbRpc('hook_emit', { p_key: key, p_ws: ws, p_event: event, p_data: (data && typeof data === 'object') ? data : {} }); }
  catch (e) { console.log('hook_emit', String(e)); return; }
  if (!out || !Array.isArray(out.subs) || !out.subs.length) return;
  const body = JSON.stringify(Object.assign({ id: out.id, event: event, created_at: new Date().toISOString() }, data));
  await Promise.all(out.subs.slice(0, 10).map(async (s) => {
    let st = 0;
    try {
      const r = await fetch(s.url, { method: 'POST', redirect: 'follow', signal: AbortSignal.timeout(5000), headers: { 'content-type': 'application/json', 'user-agent': 'Chatora-Webhook/1', 'x-chatora-event': event }, body: body });
      st = r.status;
    } catch (e) {}
    try { await sbRpc('hook_report', { p_key: key, p_id: s.id, p_status: st }); } catch (e) {}
  }));
}
async function hookWsFor(env, scope, ref) {
  if (!env || !env.AUTOMATION_SECRET) return null;
  try { return await sbRpc('hook_ws_lookup', { p_key: env.AUTOMATION_SECRET, p_scope: scope, p_ref: ref }); }
  catch (e) { console.log('hook_ws_lookup', String(e)); return null; }
}
// POST /api/v1/events: Zapier/Make/n8n/Apps Script push a contact event in. The SQL side
// finds-or-creates the contact, applies tag/unenroll side effects and opens flow runs;
// the worker executes them exactly like an inbound-message match.
async function apiEventIngest(request, env, h) {
  let a;
  try { a = await request.json(); } catch { return apiErr(400, 'bad_json', 'Body must be JSON.'); }
  if (!a || typeof a !== 'object') return apiErr(400, 'bad_json', 'Body must be a JSON object.');
  const kind = String(a.event || a.kind || '').slice(0, 20);
  const handle = String(a.handle || '').slice(0, 120);
  const name = typeof a.name === 'string' ? a.name.slice(0, 80) : '';
  const channel = typeof a.channel === 'string' ? a.channel.slice(0, 30) : '';
  const key = String(a.key !== undefined ? a.key : (a.tag !== undefined ? a.tag : '')).slice(0, 60);
  if (!/^[a-z-]{3,20}$/.test(kind) || !handle) return apiErr(422, 'invalid', 'event and handle are required. event is one of: tag-applied, tag-removed, field-changed, enroll, unenroll.');
  if (wlimited('ev:' + h, 60, 600000)) return apiErr(429, 'rate_limited', 'Too many events. Limit: 60 per 10 minutes per key.');
  let r;
  try { r = await sbRpc('api_event_start', { p_hash: h, p_kind: kind, p_handle: handle, p_name: name, p_channel: channel, p_key: key }); }
  catch (e) { console.log('api events', String(e)); return apiErr(502, 'unavailable', 'Backend unavailable, try again.'); }
  if (r === null || r === undefined) return apiErr(401, 'unauthorized', 'Invalid API key or the key lacks the events:write scope.');
  if (r.error) {
    const m = { bad_kind: 'event must be one of: tag-applied, tag-removed, field-changed, enroll, unenroll.', bad_handle: 'handle is required (max 120 characters).', bad_flow: 'enroll/unenroll need key set to a flow id (see GET /api/v1/flows).', bad_tag: 'tag events need key set to the tag (1-40 characters).', bad_field: 'field-changed needs key set to the field name.', contact_limit: 'Contact limit reached (100 on the free plan).', contact_not_found: 'No contact with this handle.', rate_limited: 'Too many flow runs for this contact. Try later.' };
    const st = r.error === 'contact_not_found' ? 404 : r.error === 'rate_limited' ? 429 : 422;
    return apiErr(st, r.error, m[r.error] || 'Invalid request.');
  }
  const contact = Object.assign({ id: r.contact_id, workspace_id: r.workspace_id }, r.contact || {});
  let failed = 0;
  for (const run of (Array.isArray(r.runs) ? r.runs : []).slice(0, 3)) {
    try {
      const w = walkFlow(run.nodes || [], 1, contact);
      await fireHooks(w, contact, run.name);
      await trackLinks(env, w, contact, run.flow_id, run.nodes);
      if (r.tg_token) for (const t of w.tg) await tgCall(r.tg_token, 'sendMessage', { chat_id: Number(w.chatId), text: t });
      await sbRpc('automation_finish', { p_key: env.AUTOMATION_SECRET, p_run_id: run.run_id, p_status: w.status, p_next_step: w.nextIdx, p_run_at: w.runAt, p_note: ('api-event; ' + w.notes.join('; ')).slice(0, 190), p_effects: w.effects });
      if (w.status === 'done') await hookEmit(env, r.workspace_id, 'flow.finished', { flow_id: run.flow_id, flow: run.name || '', contact: contact.handle || '', source: 'api-event' });
    } catch (e) {
      failed++;
      console.log('api-event run ' + run.run_id + ' ' + String(e));
      try { await sbRpc('automation_finish', { p_key: env.AUTOMATION_SECRET, p_run_id: run.run_id, p_status: 'failed', p_next_step: 1, p_run_at: null, p_note: String(e).slice(0, 190), p_effects: [] }); } catch (e2) {}
    }
  }
  await hookEmit(env, r.workspace_id, 'event.received', { kind: kind, key: key, handle: handle, fired: r.fired || 0 });
  return apiOut({ ok: true, contact_id: r.contact_id, fired: r.fired || 0, stopped: r.stopped || 0, failed: failed }, 200);
}
// POST /api/v1/messages/send: send a Telegram message to a contact the workspace already has.
async function apiMessageSend(request, env, h) {
  let a;
  try { a = await request.json(); } catch { return apiErr(400, 'bad_json', 'Body must be JSON.'); }
  if (!a || typeof a !== 'object') return apiErr(400, 'bad_json', 'Body must be a JSON object.');
  const handle = String(a.handle || '').slice(0, 120);
  const text = String(a.text || '').slice(0, 1000);
  if (!handle || !text.trim()) return apiErr(422, 'invalid', 'handle and text are required. handle looks like tg:123456789.');
  if (wlimited('ms:' + h, 30, 600000)) return apiErr(429, 'rate_limited', 'Too many messages. Limit: 30 per 10 minutes per key.');
  let r;
  try { r = await sbRpc('api_message_send', { p_hash: h, p_handle: handle, p_text: text }); }
  catch (e) { console.log('api messages.send', String(e)); return apiErr(502, 'unavailable', 'Backend unavailable, try again.'); }
  if (r === null || r === undefined) return apiErr(401, 'unauthorized', 'Invalid API key or the key lacks the messages:write scope.');
  if (r.error) {
    const m = { bad_handle: 'handle must look like tg:123456789 (a Telegram contact).', bad_text: 'text is required (max 1000 characters).', contact_not_found: 'No contact with this handle. Create it first with POST /api/v1/contacts or /api/v1/events.', not_connected: 'No Telegram bot is connected to this workspace.' };
    const st = r.error === 'contact_not_found' ? 404 : r.error === 'not_connected' ? 409 : 422;
    return apiErr(st, r.error, m[r.error] || 'Invalid request.');
  }
  const sent = await tgCall(r.tg_token, 'sendMessage', { chat_id: Number(r.chat_id), text: text });
  if (!sent) return apiErr(502, 'send_failed', 'Telegram did not accept the message.');
  if (env && env.AUTOMATION_SECRET) {
    try { await sbRpc('tg_log_out', { p_key: env.AUTOMATION_SECRET, p_id: r.connection_id, p_chat: r.chat_id, p_text: text }); } catch (e) { console.log('tg_log_out', String(e)); }
  }
  return apiOut({ ok: true, message_id: sent.message_id === undefined ? null : sent.message_id }, 200);
}
